import{_ as a,H as t,f as _,i as p}from"./chunks/framework.BH2BK_3i.js";const f=JSON.parse('{"title":"导学（二）| 汇编语言是怎么一回事？","description":"","frontmatter":{},"headers":[],"relativePath":"编程高手必学的内存知识/导学（二）-汇编语言是怎么一回事？.md","filePath":"编程高手必学的内存知识/导学（二）-汇编语言是怎么一回事？.md","lastUpdated":1779821602000}'),r={name:"编程高手必学的内存知识/导学（二）-汇编语言是怎么一回事？.md"};function n(o,e,s,d,i,l){return t(),_("div",null,[...e[0]||(e[0]=[p('<h1 id="导学-二-汇编语言是怎么一回事" tabindex="-1">导学（二）| 汇编语言是怎么一回事？ <a class="header-anchor" href="#导学-二-汇编语言是怎么一回事" aria-label="Permalink to &quot;导学（二）| 汇编语言是怎么一回事？&quot;">​</a></h1><p>你好，我是海纳。</p><p>这是我们导学的第二节，今天我们来学习汇编语言的基本原理，这节课是以视频形式讲述的，内容比较多，但我保证干货十足，非常值得你花时间好好观看学习。</p><p>你可能好奇，为什么我要花这么长时间给你讲汇编语言呢？</p><p>这是因为，汇编器将汇编语言翻译成 CPU 可以执行的机器码，汇编语言中的指令与机器码几乎是一一对应的，所以，我们学习汇编语言，其实就是在学习各种汇编指令。汇编指令大致可以分为逻辑运算和位运算指令、分支指令、字符串处理指令等三大类，这节课我都会做详细介绍。</p><p>另外，在编程语言发展过程中，人们按照编程语言中所暴露的硬件细节的多少，还会将编程语言划分为高级语言和低级语言。汇编，由于其本身包含了大量的 CPU 硬件细节，可读性非常差，被认为是低级语言，而C/C++ 等更具可读性的编程语言，则被认为是高级语言。</p><p>不过，所有的高级语言最终还是要翻译成机器码运行在 CPU 上的，查看高级语言所翻译成的机器码是程序员进行代码调试时的重要手段。所以，这节课，我还会通过实战案例向你讲解如何进行机器码级的调试。</p><p>好，现在就请你点开下面的视频，来学习今天的课程吧！</p><p>点击 <a href="https://pan.baidu.com/s/1565zP07nd69UQHOxupPktQ" target="_blank" rel="noreferrer">这里</a> 获取课件，提取码：hn66。</p>',9)])])}const m=a(r,[["render",n]]);export{f as __pageData,m as default};
